<script setup lang="ts">
import { onMounted, ref } from 'vue'
import axios from 'axios'
const base='/api/v1/admin/audience'
const headers=()=>({Authorization:`Bearer ${localStorage.getItem('admin_token') || ''}`})
const tab=ref('users'),message=ref(''),busy=ref(false),query=ref(''),offset=ref(0),total=ref(0)
const users=ref<any[]>([]),segments=ref<any[]>([]),campaigns=ref<any[]>([]),rights=ref<any[]>([]),plans=ref<any[]>([]),promos=ref<any[]>([]),detail=ref<any>(null),worker=ref<any>(null)
const entitlement=ref({code:'',type:'feature',name:'',description:'',config_json:{}}),configText=ref('{}')
const plan=ref({code:'',title:'',billing_period_days:30,price_amount:'0.00',currency:'USD',is_active:true,entitlements:[] as string[]})
const grant=ref({target:'plan',plan_id:'',entitlement_code:'',duration_days:30,trial:false})
const promo=ref({code:'',label:'',target:'plan',plan_id:'',entitlement_code:'',duration_days:30,max_redemptions:1,expires_at:''})
const segmentTitle=ref(''),activeDays=ref(''),inactiveDays=ref(''),genre=ref(''),movie=ref(''),subStatus=ref(''),telegramOnly=ref(true),previewCount=ref<number|null>(null)
const campaign=ref({title:'',segment_id:'',text:'',parse_mode:'HTML'}),buttonsText=ref('[]')
function criteria(){return {...(activeDays.value?{active_within_days:Number(activeDays.value)}:{}),...(inactiveDays.value?{inactive_over_days:Number(inactiveDays.value)}:{}),...(genre.value?{genre:genre.value}:{}),...(movie.value?{movie_id:movie.value}:{}),...(subStatus.value?{subscription_status:subStatus.value}:{}),...(telegramOnly.value?{can_send_telegram_msg:true}:{})}}
async function loadUsers(){const {data}=await axios.get(`${base}/users`,{headers:headers(),params:{q:query.value,offset:offset.value,limit:50}});users.value=data.items;total.value=data.total}
async function load(){await loadUsers();const data=await Promise.all(['segments','campaigns','entitlements','plans','promos','worker'].map(path=>axios.get(`${base}/${path}`,{headers:headers()})));segments.value=data[0]?.data;campaigns.value=data[1]?.data;rights.value=data[2]?.data;plans.value=data[3]?.data;promos.value=data[4]?.data;worker.value=data[5]?.data;if(detail.value)detail.value=(await axios.get(`${base}/users/${detail.value.id}`,{headers:headers()})).data}
async function action(fn:()=>Promise<unknown>){busy.value=true;message.value='';try{await fn();await load();message.value='Изменения сохранены.'}catch(e:any){const detail=e?.response?.data?.detail;message.value=typeof detail==='string'?detail:'Операция не выполнена. Проверьте поля, права и доступность Backend.'}finally{busy.value=false}}
async function inspect(id:string){await action(async()=>{detail.value=(await axios.get(`${base}/users/${id}`,{headers:headers()})).data})}
async function post(path:string,body:any={}){return axios.post(`${base}/${path}`,body,{headers:headers()})}
async function saveRight(){await action(async()=>{await axios.put(`${base}/entitlements/${encodeURIComponent(entitlement.value.code)}`,{...entitlement.value,config_json:JSON.parse(configText.value)},{headers:headers()})})}
async function savePlan(){await action(async()=>{await axios.put(`${base}/plans/${encodeURIComponent(plan.value.code)}`,plan.value,{headers:headers()})})}
async function issueGrant(){if(!detail.value)return;await action(async()=>{await post(`users/${detail.value.id}/grants`,{duration_days:grant.value.duration_days,trial:grant.value.target==='plan'&&grant.value.trial,...(grant.value.target==='plan'?{plan_id:grant.value.plan_id}:{entitlement_code:grant.value.entitlement_code})});detail.value=(await axios.get(`${base}/users/${detail.value.id}`,{headers:headers()})).data})}
async function preview(){await action(async()=>{previewCount.value=(await post('segments/preview',criteria())).data.total})}
async function saveSegment(){await action(()=>post('segments',{title:segmentTitle.value,criteria:criteria()}))}
async function saveCampaign(){await action(()=>post('campaigns',{...campaign.value,segment_id:campaign.value.segment_id||null,buttons:JSON.parse(buttonsText.value)}))}
async function queue(c:any){await action(async()=>{const count=(await axios.get(`${base}/campaigns/${c.id}/preview`,{headers:headers()})).data.total;if(!window.confirm(`Запустить реальную Telegram-рассылку «${c.title}»? В аудитории ${count}. Недоступные получатели будут пропущены. Отправленные сообщения нельзя отозвать.`))return;await post(`campaigns/${c.id}/queue`,{confirm:true,expected_audience:count})})}
async function createPromo(){await action(()=>post('promos',{code:promo.value.code,label:promo.value.label,duration_days:promo.value.duration_days,max_redemptions:promo.value.max_redemptions,expires_at:new Date(promo.value.expires_at).toISOString(),...(promo.value.target==='plan'?{plan_id:promo.value.plan_id}:{entitlement_code:promo.value.entitlement_code})}))}
onMounted(()=>action(load))
</script>
<template>
<section class="audience">
 <h1>Пользователи и доступ</h1><p>Единая аудитория · Telegram · сегменты · подписки и права</p>
 <nav aria-label="Разделы аудитории"><button v-for="item in [['users','Пользователи'],['marketing','Сегменты и рассылки'],['access','Подписки и права']]" :key="item[0]" :aria-pressed="tab===item[0]" @click="tab=item[0] || 'users'">{{item[1]}}</button><button @click="action(load)" :disabled="busy">Обновить</button></nav>
 <p role="status" aria-live="polite">{{busy?'Выполняется…':message}}</p>
 <div v-if="tab==='users'">
  <form @submit.prevent="offset=0;action(loadUsers)"><label>Имя пользователя <input v-model="query" maxlength="100" /></label><button :disabled="busy">Найти</button></form>
  <p>Всего: {{total}} · последние обращения обновляются не чаще раза в 5 минут</p>
  <table><thead><tr><th>Пользователь</th><th>Источник</th><th>Последняя активность</th><th>Telegram</th><th></th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td>{{u.username}}</td><td>{{u.acquisition_source||'—'}}</td><td>{{u.last_seen_at||'—'}}</td><td>{{u.can_send_telegram_msg?'Доступен':'Нет разрешения / заблокирован'}}</td><td><button @click="inspect(u.id)">Профиль и доступ</button></td></tr></tbody></table>
  <button :disabled="offset===0||busy" @click="offset-=50;action(loadUsers)">Назад</button><button :disabled="offset+50>=total||busy" @click="offset+=50;action(loadUsers)">Далее</button>
  <article v-if="detail"><h2>{{detail.username}}</h2><p>Статус: {{detail.subscription_status}} · Telegram: {{detail.telegram_username||'—'}} · язык: {{detail.telegram_language_code||'—'}}</p><p>Активные права: {{detail.entitlements.join(', ')||'нет'}}</p><p>Уникальные запуски: фильмы {{detail.activity?.movies_watched||0}}, сериалы {{detail.activity?.series_watched||0}} · жанры {{detail.activity?.favorite_genres?.join(', ')||'—'}}</p>
   <h3>Выдать доступ вручную</h3><form @submit.prevent="issueGrant"><label>Объект <select v-model="grant.target"><option value="plan">Подписка по тарифу</option><option value="right">Отдельное право</option></select></label><select v-if="grant.target==='plan'" v-model="grant.plan_id" required aria-label="Тариф"><option v-for="p in plans.filter(p=>p.is_active)" :key="p.id" :value="p.id">{{p.title}}</option></select><select v-else v-model="grant.entitlement_code" required aria-label="Право"><option v-for="r in rights" :key="r.code" :value="r.code">{{r.name}}</option></select><label>Дней <input type="number" min="1" max="36500" v-model.number="grant.duration_days" required /></label><label v-if="grant.target==='plan'"><input type="checkbox" v-model="grant.trial" /> Trial</label><button :disabled="busy">Выдать</button></form>
   <h3>Подписки</h3><ul><li v-for="s in detail.subscriptions" :key="s.id">{{s.plan_id}} · {{s.status}} · до {{s.expires_at}} <button @click="action(()=>post(`subscriptions/${s.id}/cancel`))">Отключить продление</button><button @click="action(()=>post(`subscriptions/${s.id}/revoke`))">Отозвать доступ</button></li></ul>
   <h3>Прямые права</h3><ul><li v-for="g in detail.direct_grants" :key="g.id">{{g.entitlement_code}} · до {{g.expires_at}} {{g.revoked_at?'отозвано':''}} <button :disabled="!!g.revoked_at||busy" @click="action(()=>post(`grants/${g.id}/revoke`))">Отозвать</button></li></ul>
  </article>
 </div>
 <div v-if="tab==='marketing'">
  <h2>Сегмент аудитории</h2><p>Условия активности и подписки объединяются через И. Жанр / фильм — через ИЛИ. Счётчики означают уникальные запуски, не досмотры.</p>
  <form @submit.prevent="saveSegment"><label>Название <input v-model="segmentTitle" maxlength="200" required /></label><label>Активны за дней <input type="number" min="1" max="3650" v-model="activeDays" /></label><label>Неактивны больше дней <input type="number" min="1" max="3650" v-model="inactiveDays" /></label><label>Жанр (slug) <input v-model="genre" /></label><label>Фильм (UUID) <input v-model="movie" /></label><label>Подписка <select v-model="subStatus"><option value="">Любая</option><option v-for="s in ['free','trial','active_paid','expired','churned']" :key="s">{{s}}</option></select></label><label><input type="checkbox" v-model="telegramOnly" /> Telegram доступен</label><button type="button" @click="preview" :disabled="busy">Посчитать аудиторию</button><span v-if="previewCount!==null">{{previewCount}} пользователей</span><button :disabled="busy">Сохранить сегмент</button></form>
  <ul><li v-for="s in segments" :key="s.id">{{s.title}} · {{JSON.stringify(s.criteria)}}</li></ul>
  <h2>Новая рассылка</h2><p>Сначала создаётся черновик. Отправка — только отдельной подтверждённой командой. /stop в боте отключает сообщения.</p>
  <form @submit.prevent="saveCampaign"><label>Название <input v-model="campaign.title" required maxlength="200" /></label><label>Аудитория <select v-model="campaign.segment_id"><option value="">Все зрители</option><option v-for="s in segments" :key="s.id" :value="s.id">{{s.title}}</option></select></label><label>Формат <select v-model="campaign.parse_mode"><option>HTML</option><option>MarkdownV2</option></select></label><label>Сообщение <textarea v-model="campaign.text" required maxlength="3500" rows="6"></textarea></label><label>Кнопки (JSON: [{"text":"Открыть","url":"https://…"}]) <textarea v-model="buttonsText" rows="3"></textarea></label><button :disabled="busy">Создать черновик</button></form>
  <table><thead><tr><th>Кампания</th><th>Статус</th><th>Аудитория</th><th>Отправлено / blocked / ошибки / неопределённо / пропущено</th><th>Переходы (уникальные)</th><th></th></tr></thead><tbody><tr v-for="c in campaigns" :key="c.id"><td>{{c.title}}</td><td>{{c.status}}</td><td>{{c.audience_count}}</td><td>{{c.deliveries.sent||0}} / {{c.deliveries.blocked||0}} / {{c.deliveries.failed||0}} / {{c.deliveries.unknown||0}} / {{c.deliveries.skipped||0}}</td><td>{{c.clicks}}</td><td><button v-if="c.status==='draft'" @click="queue(c)" :disabled="busy">Подтвердить отправку</button><button v-if="['queued','sending'].includes(c.status)" @click="action(()=>post(`campaigns/${c.id}/cancel`))" :disabled="busy">Остановить очередь</button></td></tr></tbody></table>
  <p>Неопределённые доставки не повторяются автоматически: Telegram не гарантирует exactly-once при обрыве связи.</p><p>Bot API настроен: {{worker?.bot_configured?'да':'нет'}}. Воркер работает только на Backend, не на ПК.</p><ul><li v-for="s in worker?.states||[]" :key="s.key">{{s.key}} · успешный опрос {{s.last_success_at||'не подтверждён'}} · ошибка {{s.last_error_code||'нет'}}</li></ul>
 </div>
 <div v-if="tab==='access'">
  <h2>Реестр прав</h2><form @submit.prevent="saveRight"><label>Code <input v-model="entitlement.code" required maxlength="100" /></label><label>Тип / плагин <input v-model="entitlement.type" required maxlength="100" /></label><label>Название <input v-model="entitlement.name" required maxlength="200" /></label><label>Описание <input v-model="entitlement.description" maxlength="4000" /></label><label>Конфигурация JSON <textarea v-model="configText"></textarea></label><button :disabled="busy">Сохранить право</button></form><ul><li v-for="r in rights" :key="r.code">{{r.code}} · {{r.type}} · {{r.name}} <button @click="entitlement={...r};configText=JSON.stringify(r.config_json)">Редактировать</button></li></ul>
  <h2>Тарифы</h2><p>Смена набора прав влияет на текущие подписки. Неактивный тариф закрыт для новых выдач, но сохраняет ранее выданный доступ.</p><form @submit.prevent="savePlan"><label>Code <input v-model="plan.code" required /></label><label>Название <input v-model="plan.title" required /></label><label>Период, дней <input type="number" min="1" max="36500" v-model.number="plan.billing_period_days" required /></label><label>Цена <input type="number" min="0" step="0.01" v-model="plan.price_amount" required /></label><label>Валюта <input v-model="plan.currency" pattern="[A-Z]{3}" required /></label><label><input type="checkbox" v-model="plan.is_active" /> Активен для новых выдач</label><label>Права <select v-model="plan.entitlements" multiple><option v-for="r in rights" :key="r.code" :value="r.code">{{r.code}}</option></select></label><button :disabled="busy">Сохранить тариф</button></form><ul><li v-for="p in plans" :key="p.id">{{p.title}} · {{p.price_amount}} {{p.currency}} / {{p.billing_period_days}} дней · {{p.entitlements.join(', ')}} <button @click="plan={code:p.code,title:p.title,billing_period_days:p.billing_period_days,price_amount:String(p.price_amount),currency:p.currency,is_active:p.is_active,entitlements:[...p.entitlements]}">Редактировать</button></li></ul>
  <h2>Промокоды</h2><form @submit.prevent="createPromo"><label>Код (8–64 символа) <input v-model="promo.code" minlength="8" maxlength="64" pattern="[A-Za-z0-9_-]+" required autocomplete="off" /></label><label>Метка <input v-model="promo.label" required /></label><label>Выдать <select v-model="promo.target"><option value="plan">Тариф</option><option value="right">Право</option></select></label><select v-if="promo.target==='plan'" v-model="promo.plan_id" required aria-label="Тариф промокода"><option v-for="p in plans.filter(p=>p.is_active)" :key="p.id" :value="p.id">{{p.title}}</option></select><select v-else v-model="promo.entitlement_code" required aria-label="Право промокода"><option v-for="r in rights" :key="r.code" :value="r.code">{{r.code}}</option></select><label>Дней доступа <input type="number" min="1" max="36500" v-model.number="promo.duration_days" required /></label><label>Лимит применений <input type="number" min="1" max="1000000" v-model.number="promo.max_redemptions" required /></label><label>Действует до (местное время) <input type="datetime-local" v-model="promo.expires_at" required /></label><button :disabled="busy">Создать</button></form><ul><li v-for="p in promos" :key="p.id">{{p.label}} · {{p.redemption_count}} / {{p.max_redemptions}} · до {{p.expires_at}} <button :disabled="!p.is_active||busy" @click="action(()=>post(`promos/${p.id}/disable`))">Отключить</button></li></ul>
  <p>Сохранение тарифа и выдача manual_admin не списывают деньги. Автоматический биллинг и платёжные шлюзы не подключены.</p>
 </div>
</section>
</template>
<style scoped>
.audience{padding:24px;max-width:1400px}.audience nav,.audience form{display:flex;flex-wrap:wrap;gap:12px;margin:20px 0;align-items:end}.audience label{display:flex;flex-direction:column;gap:6px}.audience input,.audience select,.audience textarea{padding:9px;border:1px solid #526078;border-radius:6px;color:inherit;background:#172033}.audience button{padding:9px 14px;background:#273a58;color:#fff;border:1px solid #526078;border-radius:6px;cursor:pointer}.audience button[aria-pressed=true]{border-color:#69baff}.audience button:disabled{opacity:.5;cursor:default}.audience table{width:100%;border-collapse:collapse;display:block;overflow-x:auto}.audience td,.audience th{padding:12px;text-align:left;border-bottom:1px solid #394457}.audience article{padding:20px;border:1px solid #394457;margin-top:24px;border-radius:8px}.audience textarea{min-width:300px}.audience li{margin:12px 0;overflow-wrap:anywhere}.audience p{color:#b8c6da;line-height:1.6}
</style>
